#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""The Cycle dependency ledger: what a `depends_on` edge is resolved against.

Without this, an edge declaring a condition stronger than `done` can never
resolve. The #304 gate correctly refuses it forever, which is safe but useless:
the dependent unit is blocked with no mechanism that could ever unblock it. This
module is that mechanism.

## An event is a CLAIM, not proof

A producer saying "my contract is published" is an assertion; whether the
consumer can CHECK it differs per condition:

    contract_published / artifact_published   verifiable: recompute the digest
                                              against the producer's ref
    integrated                                verifiable: ancestry against the
                                              Cycle integration ref; under an
                                              incremental policy, also a green
                                              attestation for that exact HEAD
    done                                      claim only -- the producer's own
                                              claim about itself
    environment_ready                         claim only -- an out-of-band
                                              assertion nothing implies

An unverified claim NEVER unblocks downstream work -- there is no toggle, so a
claim-only condition fails closed. That is a strong stance with a real cost: a
plain-string `depends_on` becomes unusable for anything but board state, and the
PO has to name a verifiable condition instead. That is precisely #303's "prefer
the smallest sufficient condition", and it is the only way "an upstream
integration event can SAFELY unblock a downstream Work Unit" is true rather than
aspirational.

## Where events live

The committed `.synaptory/cycles/<cycle-id>/events/` files are the SOURCE OF
TRUTH; `dependency-ledger.json` in the orchestrator tree is a local materialized
cache with a `refreshed_at`. The cache is never authoritative and can be deleted
safely -- it is rebuilt from git.

ONE DIRECTORY PER CYCLE, and one ref to read it from. The predecessor split both
per lane, which only mattered because a lane was the thing publishing and the
thing pushing. `SPD-194` retires the Workstream: a Work Unit is owned by the
Cycle that admitted it, so there is no second publisher to keep apart and no
second branch to enumerate. `spq_paths.committed_events_dir` and
`spq_paths.integration_branch` are the single definitions of both, and this
module reads them rather than re-deriving either.

## Propagation is human-gated, by the project's own rules

`modes/init.md` forbids agents committing or pushing, so every cross-clone
unblock has a mandatory human push in the middle. `publish` therefore prints the
exact push command, and `dep_status` distinguishes `dep_event_local_only`
(written, not pushed) from an edge with nothing published yet, so the latency
never looks like a bug.

Python 3.9 compatible: this file is projected into every host package.
"""

from __future__ import annotations

import hashlib
import json
import os
import subprocess
from typing import Any, Dict, List, Optional, Sequence, Tuple

SCHEMA_VERSION = "1.0"
KIND = "spq.cycle.event"
INCREMENTAL_EVALUATION_SCHEMA_VERSION = "1.0"
INCREMENTAL_EVALUATION_KIND = "spq.incremental.evaluation"

# Default staleness ceiling for the local cache, in seconds. Past this, a
# non-local dependency fails closed rather than resolving against a snapshot
# that may predate the event it is waiting for.
DEFAULT_MAX_LEDGER_AGE_S = 900

# Conditions a consumer can VERIFY for itself, versus ones it can only take on
# trust. Kept explicit rather than inferred, because "which of these did we
# actually check" is the whole question.
VERIFIABLE = frozenset({"contract_published", "artifact_published", "integrated"})
CLAIM_ONLY = frozenset({"done", "environment_ready", "cycle_integrated"})


class LedgerError(RuntimeError):
    """A refusal the caller must surface, not swallow."""


# ── the Cycle's own facts, read from one place each ─────────────────────────


def integration_ref(manifest: Dict[str, Any]) -> str:
    """The ref an `integrated` claim is checked for ancestry against.

    Read through here rather than off the manifest, because the declaration
    `cycle_records` seals carries no `integration_ref`: the per-lane branches
    the predecessor's manifest enumerated are gone with the Workstream, and
    what a Cycle has is one integration ref plus the trunk it integrates into
    at Checkpoint (`SC-MTH-007`). `spq_paths.integration_branch` defines it.

    An explicit `integration_ref` on the declaration still wins, so a project
    that pins a different ref is not overridden by a default.
    """
    declared = str(manifest.get("integration_ref") or "").strip()
    if declared:
        return declared
    cycle_id = str(manifest.get("cycle_id") or "").strip()
    if not cycle_id:
        return ""
    import spq_paths

    try:
        return spq_paths.integration_branch(cycle_id)
    except Exception:  # noqa: BLE001 - a malformed identity names no ref
        return ""


def admitted_ids(manifest: Dict[str, Any]) -> List[str]:
    """The Work Unit ids this Cycle admitted, from the declaration's own key.

    `cycle_records` names the set `admitted_units`. This existed as
    `spq_manifest.owners`, which read `work_units` and returned a unit -> lane
    map: against a sealed declaration it therefore answered `{}`, and every
    publish refused with "not admitted to Cycle X" for a unit the Cycle had
    admitted. Same class as the `advance_kernel` / `pipeline_board` re-point.
    """
    import cycle_records

    return [
        str(unit.get("id"))
        for unit in manifest.get(cycle_records.UNITS_FIELD) or []
        if isinstance(unit, dict) and unit.get("id")
    ]


# ── event identity ──────────────────────────────────────────────────────────


def canonical_bytes(event: Dict[str, Any]) -> bytes:
    body = {k: v for k, v in event.items() if k != "event_id"}
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def event_id(event: Dict[str, Any]) -> str:
    """Content-addressed id.

    Content addressing is not decoration: it makes a re-shipped or re-pulled
    event self-deduplicating, and it maps directly onto the control plane's
    `client_event_id` idempotency index without inventing a second scheme.
    """
    return hashlib.sha256(canonical_bytes(event)).hexdigest()[:16]


def incremental_evaluation_id(attestation: Dict[str, Any]) -> str:
    """Content identity for one tree-bound incremental regression verdict."""
    body = {k: v for k, v in attestation.items() if k != "attestation_id"}
    encoded = json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()[:16]


def build_incremental_evaluation(
    *,
    cycle_id: str,
    manifest_hash: str,
    unit_id: str,
    candidate_sha: str,
    evaluated_head: str,
    integration_ref: str,
    checks: Dict[str, Any],
    evaluated_at: str,
) -> Dict[str, Any]:
    """Build the attestation handed from evaluation to event publication.

    It is intentionally data, not a mutable cache.  Publication re-checks its
    content identity, the candidate ancestry, and that ``integration_ref``
    still resolves to the exact evaluated HEAD.  A later merge therefore
    invalidates an earlier green result instead of silently inheriting it.
    """
    attestation: Dict[str, Any] = {
        "schema_version": INCREMENTAL_EVALUATION_SCHEMA_VERSION,
        "kind": INCREMENTAL_EVALUATION_KIND,
        "cycle_id": str(cycle_id),
        "manifest_hash": str(manifest_hash),
        "unit_id": str(unit_id),
        "candidate_sha": str(candidate_sha),
        "evaluated_head": str(evaluated_head),
        "integration_ref": str(integration_ref),
        "verdict": "green",
        "checks": dict(checks),
        "evaluated_at": str(evaluated_at),
    }
    attestation["attestation_id"] = incremental_evaluation_id(attestation)
    return attestation


def build_event(
    *,
    cycle_id: str,
    manifest_hash: str,
    unit_id: str,
    condition: str,
    output: Optional[Dict[str, Any]] = None,
    commit_sha: str = "",
    integration_ref: str = "",
    verification: Optional[Dict[str, Any]] = None,
    published_at: str = "",
    published_by: str = "",
    runner_id: str = "",
    seq: int = 0,
) -> Dict[str, Any]:
    """One event record. `manifest_hash` is the WIRE key and stays spelled that
    way for a release, so a control plane built against the old contract still
    decodes; the sealed DOCUMENT it names has one key (`declaration_hash`).

    No `workstream_id`. It named the lane that published, and `runner_id`
    answers that question now -- an id `spq_paths` validates, rather than a
    topology entry the declaration no longer carries.
    """
    event = {
        "schema_version": SCHEMA_VERSION,
        "kind": KIND,
        "seq": int(seq),
        "cycle_id": str(cycle_id),
        "manifest_hash": str(manifest_hash),
        "runner_id": str(runner_id),
        "unit_id": str(unit_id),
        "condition": str(condition),
        "output": dict(output) if output else None,
        "commit_sha": str(commit_sha),
        "integration_ref": str(integration_ref),
        "verification": dict(verification) if verification else None,
        "published_at": str(published_at),
        "published_by": str(published_by),
    }
    event["event_id"] = event_id(event)
    return event


# ── git plumbing, reused from the barrier ───────────────────────────────────


def _git(project_dir: str, *args: str) -> Tuple[int, str, str]:
    try:
        result = subprocess.run(
            ["git", *args],
            cwd=str(project_dir),
            capture_output=True,
            text=True,
            timeout=60,
        )
    except Exception as exc:  # noqa: BLE001 - no git, or a hang
        return 1, "", str(exc)
    return result.returncode, result.stdout, result.stderr


def _is_ancestor(project_dir: str, sha: str, of: str) -> bool:
    if not sha or not of:
        return False
    code, _, _ = _git(project_dir, "merge-base", "--is-ancestor", sha, of)
    return code == 0


def _ref_head(project_dir: str, ref: str) -> str:
    if not ref:
        return ""
    code, out, _ = _git(project_dir, "rev-parse", "--verify", "%s^{commit}" % ref)
    return out.strip() if code == 0 else ""


def _verify_incremental_evaluation(
    project_dir: str,
    *,
    manifest: Dict[str, Any],
    unit_id: str,
    commit_sha: str,
    evaluation: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Bind an ``integrated`` event to the exact tree that passed regression."""
    if not isinstance(evaluation, dict):
        return {
            "verified": False,
            "detail": (
                "incremental integration requires the evaluation attestation "
                "returned by evaluate-incremental"
            ),
        }

    expected = {
        "schema_version": INCREMENTAL_EVALUATION_SCHEMA_VERSION,
        "kind": INCREMENTAL_EVALUATION_KIND,
        "cycle_id": str(manifest.get("cycle_id") or ""),
        "manifest_hash": str(manifest.get("declaration_hash") or ""),
        "unit_id": str(unit_id),
        "candidate_sha": str(commit_sha),
        "integration_ref": integration_ref(manifest),
        "verdict": "green",
    }
    mismatched = [
        key for key, value in expected.items() if str(evaluation.get(key) or "") != value
    ]
    if mismatched:
        return {
            "verified": False,
            "detail": "incremental evaluation does not match %s" % ", ".join(mismatched),
        }

    declared_id = str(evaluation.get("attestation_id") or "")
    if not declared_id or declared_id != incremental_evaluation_id(evaluation):
        return {
            "verified": False,
            "detail": "incremental evaluation attestation_id is missing or invalid",
        }

    evaluated_head = str(evaluation.get("evaluated_head") or "")
    ref = expected["integration_ref"]
    current_head = _ref_head(project_dir, ref)
    if not current_head:
        return {
            "verified": False,
            "detail": "integration ref %s is unavailable; fetch it and retry" % ref,
        }
    if evaluated_head != current_head:
        return {
            "verified": False,
            "detail": (
                "incremental evaluation covered %s but %s is now %s; re-run "
                "evaluate-incremental on the current tree"
                % (evaluated_head[:12] or "<none>", ref, current_head[:12])
            ),
        }
    if not _is_ancestor(project_dir, commit_sha, evaluated_head):
        return {
            "verified": False,
            "detail": (
                "candidate %s was not present in evaluated HEAD %s"
                % (commit_sha[:12], evaluated_head[:12])
            ),
        }

    checks = evaluation.get("checks")
    if not isinstance(checks, dict):
        return {
            "verified": False,
            "detail": "incremental evaluation checks must be an object",
        }

    requires = [
        str(value)
        for value in ((manifest.get("integration_policy") or {}).get("merge_requires") or [])
    ]
    regression = checks.get("regression_green") or {}
    if "regression_green" in requires and regression.get("passed") is not True:
        return {
            "verified": False,
            "detail": "incremental evaluation does not attest a green regression",
        }

    return {
        "verified": True,
        "detail": (
            "%s was present in evaluated HEAD %s, which is still the head of %s"
            % (commit_sha[:12], evaluated_head[:12], ref)
        ),
        "command": "git merge-base --is-ancestor %s %s" % (
            commit_sha, evaluated_head,
        ),
        "attestation_id": declared_id,
        "evaluated_head": evaluated_head,
        "evaluation": dict(evaluation),
    }


# ── publishing ──────────────────────────────────────────────────────────────


def publish(
    project_dir: str,
    *,
    cycle_id: str,
    manifest: Dict[str, Any],
    unit_id: str,
    condition: str,
    output: Optional[Dict[str, Any]] = None,
    evaluation: Optional[Dict[str, Any]] = None,
    commit_sha: str = "",
    published_by: str = "",
    runner_id: str = "",
    verify: bool = True,
) -> Dict[str, Any]:
    """Record that `unit_id` reached `condition`. Verifies before writing.

    Verification happens at PUBLISH time, where the facts are available: this
    clone has the ref, the digest script and the commit. A consumer re-checking
    later can only re-run the cheap parts, so an event that was never checked
    here is an event nobody checks.

    NO `workstream_id`, AND NO OWNERSHIP CHECK. The predecessor refused a
    publish about "another lane's Work Unit", which was a real guard while a
    lane was the thing publishing. `SPD-194` retires the Workstream: a unit is
    owned by the Cycle that admitted it, so admission IS the ownership check
    and a second one would compare an id against a lane that does not exist.
    `runner_id` records which executor published, which is the question the
    lane id was actually answering.
    """
    import cycle_records
    import spq_paths
    import state_store

    if condition not in cycle_records.DEP_CONDITIONS:
        raise LedgerError(
            "unknown condition %r (known: %s). `cycle_integrated` retired with "
            "the Coordination Cycle (`SPD-194`): unorderable work is co-admitted "
            "to one Cycle, so there is no second Cycle to wait on"
            % (condition, ", ".join(cycle_records.DEP_CONDITIONS))
        )

    if unit_id not in admitted_ids(manifest):
        raise LedgerError(
            "%s is not admitted to Cycle %s, so no event about it can be "
            "meaningful" % (unit_id, cycle_id)
        )

    verification = None
    if verify:
        verification = verify_condition(
            project_dir,
            manifest=manifest,
            unit_id=unit_id,
            condition=condition,
            output=output,
            commit_sha=commit_sha,
            evaluation=evaluation,
        )
        if verification.get("verified") is False:
            raise LedgerError(
                "refusing to publish %s=%s for %s: %s"
                % (condition, "verified", unit_id, verification.get("detail"))
            )

    events_dir = spq_paths.committed_events_dir(project_dir, cycle_id)
    os.makedirs(events_dir, exist_ok=True)
    seq = len([n for n in os.listdir(events_dir) if n.endswith(".json")]) + 1

    event = build_event(
        cycle_id=cycle_id,
        manifest_hash=str(manifest.get(cycle_records.HASH_FIELD) or ""),
        unit_id=unit_id,
        condition=condition,
        output=output,
        commit_sha=commit_sha,
        integration_ref=integration_ref(manifest),
        verification=verification,
        published_at=state_store.now_iso(),
        published_by=published_by,
        runner_id=runner_id,
        seq=seq,
    )

    # Defence in depth for review finding P1(4). `cycle_records.UNIT_ID_RE`
    # refuses a malformed id at admission, but this is the write that would
    # escape, and a containment check at the write does not depend on
    # validation having run -- a declaration written by an older plugin, or a
    # caller reaching this directly, must still not be able to place a file
    # outside the events directory.
    if not cycle_records.UNIT_ID_RE.match(str(unit_id)):
        raise LedgerError(
            "%r is not a valid Work Unit id: ids become event filenames, so "
            "they must match %s"
            % (unit_id, cycle_records.UNIT_ID_RE.pattern)
        )
    path = os.path.join(
        events_dir, "%04d-%s-%s.json" % (seq, condition, unit_id)
    )
    resolved = os.path.realpath(path)
    root = os.path.realpath(events_dir)
    if not resolved.startswith(root + os.sep):
        raise LedgerError(
            "refusing to write a Cycle event outside %s (resolved to %s)"
            % (root, resolved)
        )
    state_store.write_json_atomic(path, event)

    # Report it. The ledger is otherwise invisible to the control plane, so a
    # reader could see a Cycle's gates and still not learn what satisfied a
    # dependency, or when. Best-effort and last: git is authoritative, and the
    # barrier reads the committed event rather than this.
    try:
        from gate_emitter import emit_dependency_published

        emit_dependency_published(
            unit_id,
            target_type="work_unit",
            published_by=published_by,
            reason="%s (cycle %s, event %s)"
            % (condition, cycle_id, event["event_id"]),
            project_dir=project_dir,
        )
    except Exception:  # noqa: BLE001 - observation must never block delivery
        pass

    return {
        "event": event,
        "path": path,
        # The project's own rules forbid agents pushing, so the propagation
        # step is a human's. Naming the command is what stops the latency
        # looking like a failure.
        "push_command": "git add %s && git commit -m 'spq: %s %s' && git push"
        % (os.path.relpath(path, project_dir), condition, unit_id),
    }


def verify_condition(
    project_dir: str,
    *,
    manifest: Dict[str, Any],
    unit_id: str,
    condition: str,
    output: Optional[Dict[str, Any]] = None,
    commit_sha: str = "",
    evaluation: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Can this consumer CHECK the claim, and does it hold?

    Returns `{"verified": True|False|None, "detail": str}`. `None` means
    claim-only -- not a failure, but not proof either, and the dependency gate
    treats it as unproven unless the project opts in.
    """
    if condition in CLAIM_ONLY:
        return {
            "verified": None,
            "detail": (
                "%s is an assertion this clone cannot check: %s"
                % (
                    condition,
                    "it is the producer's own claim about itself"
                    if condition == "done"
                    else "it is asserted out of band",
                )
            ),
        }

    if condition == "integrated":
        ref = integration_ref(manifest)
        if not commit_sha:
            return {"verified": False, "detail": "integrated requires --sha"}
        if not _is_ancestor(project_dir, commit_sha, ref):
            return {
                "verified": False,
                "detail": (
                    "%s is not an ancestor of %s, so the work is not on the "
                    "Cycle integration ref" % (commit_sha[:12], ref)
                ),
            }
        policy = manifest.get("integration_policy") or {}
        if str(policy.get("mode") or "at_sync") == "incremental":
            checked = _verify_incremental_evaluation(
                project_dir,
                manifest=manifest,
                unit_id=unit_id,
                commit_sha=commit_sha,
                evaluation=evaluation,
            )
            if not checked.get("verified"):
                return checked
            return checked
        return {
            "verified": True,
            "detail": "%s is an ancestor of %s" % (commit_sha[:12], ref),
            "command": "git merge-base --is-ancestor %s %s" % (commit_sha, ref),
        }

    # contract_published / artifact_published: the digest must match what the
    # producer's own digest script computes, using the SAME script the barrier
    # runs at Sync. Two spellings of "the digest" is a check that quietly stops
    # checking.
    declared = (output or {}).get("digest")
    if not declared:
        return {
            "verified": False,
            "detail": (
                "%s requires an output digest: without one the event asserts "
                "that something was published but not WHAT" % condition
            ),
        }
    script = str((manifest.get("verification") or {}).get("digest_script") or "")
    path = (output or {}).get("id") or ""
    if not script or not os.path.exists(os.path.join(project_dir, script)):
        return {
            "verified": None,
            "detail": (
                "no digest_script configured, so the declared digest %s cannot "
                "be recomputed here" % str(declared)[:16]
            ),
        }
    code, out, err = _git(project_dir, "rev-parse", "--show-toplevel")
    _ = code, out, err
    try:
        result = subprocess.run(
            ["bash", script, str(path)],
            cwd=str(project_dir),
            capture_output=True,
            text=True,
            timeout=120,
        )
    except Exception as exc:  # noqa: BLE001
        return {"verified": False, "detail": "digest script failed: %s" % exc}
    if result.returncode != 0:
        return {
            "verified": False,
            "detail": "digest script exited %d: %s"
            % (result.returncode, result.stderr.strip()[:200]),
        }
    recomputed = result.stdout.strip().split()[-1] if result.stdout.strip() else ""
    if recomputed != str(declared):
        return {
            "verified": False,
            "detail": (
                "declared digest %s does not match the recomputed %s for %s"
                % (str(declared)[:16], recomputed[:16], path)
            ),
        }
    return {
        "verified": True,
        "detail": "digest %s matches for %s" % (recomputed[:16], path),
        "command": "bash %s %s" % (script, path),
    }


# ── reading ─────────────────────────────────────────────────────────────────


def _local_events(project_dir: str, cycle_id: str) -> List[Dict[str, Any]]:
    import spq_paths
    import state_store

    root = spq_paths.committed_events_dir(project_dir, cycle_id)
    found: List[Dict[str, Any]] = []
    if not os.path.isdir(root):
        return found
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in sorted(filenames):
            if not name.endswith(".json"):
                continue
            event = state_store.read_json(os.path.join(dirpath, name))
            if event:
                found.append(event)
    return found


def refresh(
    project_dir: str,
    cycle_id: str,
    *,
    manifest: Optional[Dict[str, Any]] = None,
    remote: str = "origin",
    fetch: bool = True,
) -> Dict[str, Any]:
    """Rebuild the local cache from git. Never merges.

    Reads the Cycle's committed events off its remote integration ref with
    `git show`: refreshing the ledger must never mutate the working tree, or
    reading a dependency would be a side-effecting operation.

    ONE REF, not a list of lane branches. The predecessor enumerated
    `manifest["workstreams"]`, which a sealed declaration no longer carries --
    so this loop ran zero times against a `cycle_records` document and the
    refresh silently degraded to "whatever is already in this working tree",
    reporting `refresh_ok: True` for having read nothing remote. `SPD-194`
    leaves a Cycle with one integration ref, which `spq_paths` defines.
    """
    import spq_paths
    import state_store

    fetch_ok = True
    fetch_detail = "skipped"
    if fetch:
        code, _, err = _git(project_dir, "fetch", remote, "--quiet")
        fetch_ok = code == 0
        fetch_detail = "ok" if fetch_ok else err.strip()[:200]

    events: Dict[str, Dict[str, Any]] = {}
    unreadable: List[Dict[str, str]] = []
    for event in _local_events(project_dir, cycle_id):
        events[str(event.get("event_id"))] = event

    remote_ref = ""
    if manifest:
        local_ref = integration_ref(manifest)
        remote_ref = "%s/%s" % (remote, local_ref) if local_ref else ""
    if remote_ref:
        rel_root = os.path.relpath(
            spq_paths.committed_events_dir(project_dir, cycle_id), project_dir
        )
        code, listing, err = _git(
            project_dir, "ls-tree", "-r", "--name-only", remote_ref, "--", rel_root,
        )
        if code != 0:
            # A ref this clone cannot read is NOT an empty ref. Swallowing it
            # turned "I could not read the integration ref" into "nothing has
            # been published", which reads the same as a satisfied-nothing-yet
            # ledger while actually being no information at all. For one
            # consumer asking about one upstream that was survivable, since
            # no-event is already the fail-closed direction; for anything
            # aggregating across the Cycle it is a green built on silence.
            #
            # But a branch that DOES NOT EXIST YET is the normal state at the
            # start of every Cycle -- nobody has pushed. Treating that as
            # unreadable would make the ledger permanently stale until the
            # first push, which is a fail-closed that never opens. Only a ref
            # that resolves and still cannot be listed is a real fault.
            # (`ls-tree` on a resolvable ref exits 0 with empty output when the
            # path is simply absent from that tree.)
            if _ref_head(project_dir, remote_ref):
                unreadable.append(
                    {"ref": remote_ref, "error": err.strip()[:200]}
                )
        else:
            for rel in listing.splitlines():
                rel = rel.strip()
                if not rel.endswith(".json"):
                    continue
                code, blob, _ = _git(
                    project_dir, "show", "%s:%s" % (remote_ref, rel)
                )
                if code != 0:
                    continue
                try:
                    event = json.loads(blob)
                except ValueError:
                    continue
                if isinstance(event, dict) and event.get("event_id"):
                    events[str(event["event_id"])] = event

    if unreadable and fetch_ok:
        fetch_detail = "unreadable refs: %s" % ", ".join(
            "%s (%s)" % (u["ref"], u["error"]) for u in unreadable
        )
    cache = {
        "schema_version": SCHEMA_VERSION,
        "cycle_id": cycle_id,
        "refreshed_at": state_store.now_iso(),
        # An unreadable ref makes this refresh incomplete, and `snapshot` derives
        # `fresh` from here -- so the dependency gate fails closed on it rather
        # than resolving against a partial view.
        "refresh_ok": fetch_ok and not unreadable,
        "refresh_detail": fetch_detail,
        "unreadable_refs": unreadable,
        "events": sorted(events.values(), key=lambda e: (e.get("seq") or 0)),
    }
    state_store.write_json_atomic(spq_paths.ledger_path(project_dir, cycle_id), cache)
    return cache


def snapshot(
    project_dir: str,
    cycle_id: str,
    *,
    max_age_s: int = DEFAULT_MAX_LEDGER_AGE_S,
    allow_stale: bool = False,
) -> Dict[str, Any]:
    """The cached ledger, with an honest freshness verdict.

    `fresh: False` is not an error here; it is the fact the dependency gate
    needs so a non-local edge can fail closed rather than resolve against a
    snapshot that may predate the very event it is waiting for.
    """
    import datetime as _dt

    import spq_paths
    import state_store

    cache = state_store.read_json(spq_paths.ledger_path(project_dir, cycle_id))
    if not cache:
        return {
            "cycle_id": cycle_id,
            "events": [],
            "fresh": False,
            "detail": "no local ledger cache; run refresh",
        }

    fresh = True
    detail = "cache is current"
    stamp = cache.get("refreshed_at")
    if not cache.get("refresh_ok"):
        fresh = False
        detail = "last refresh failed: %s" % cache.get("refresh_detail")
    elif stamp:
        try:
            when = _dt.datetime.fromisoformat(str(stamp))
            now = _dt.datetime.now(_dt.timezone.utc)
            age = (now - when).total_seconds()
            if age > max_age_s:
                fresh = False
                detail = "cache is %ds old (ceiling %ds)" % (int(age), max_age_s)
        except ValueError:
            fresh = False
            detail = "unparseable refreshed_at"

    if allow_stale:
        fresh = True
        detail += " (staleness waived)"
    return {
        "cycle_id": cycle_id,
        "events": list(cache.get("events") or []),
        "fresh": fresh,
        "detail": detail,
        "refreshed_at": stamp,
    }


def satisfied_map(
    snap: Dict[str, Any], manifest: Dict[str, Any]
) -> Dict[str, Dict[str, Any]]:
    """unit_id -> the STRONGEST recorded condition, for the dependency gate.

    Events from a different Cycle or a different manifest revision are ignored
    rather than merged: an event recorded against a superseded admitted set may
    describe a unit that no longer exists, and letting it satisfy an edge would
    be resolving against a Cycle that is gone.
    """
    import cycle_records
    import spq_manifest

    cycle_id = str(manifest.get("cycle_id") or "")
    manifest_hash = str(manifest.get(cycle_records.HASH_FIELD) or "")
    best: Dict[str, Dict[str, Any]] = {}
    for event in snap.get("events") or []:
        if str(event.get("cycle_id") or "") != cycle_id:
            continue
        if manifest_hash and str(event.get("manifest_hash") or "") != manifest_hash:
            continue
        unit = str(event.get("unit_id") or "")
        condition = str(event.get("condition") or "")
        if not unit or condition not in spq_manifest.CONDITION_RANK:
            continue
        current = best.get(unit)
        if current and not spq_manifest.satisfies(
            str(current["condition"]), condition
        ):
            continue
        verification = event.get("verification") or {}
        best[unit] = {
            "condition": condition,
            "verified": verification.get("verified") is True,
            "sha": event.get("commit_sha"),
            "event_id": event.get("event_id"),
            "runner_id": event.get("runner_id"),
            "published_at": event.get("published_at"),
        }
    return best


def local_only_units(project_dir: str, cycle_id: str) -> List[str]:
    """Units whose event is written here but not yet visible on the remote.

    This is what lets `dep_status` say `dep_event_local_only` instead of
    reporting nothing published. Without the distinction, "I published it" and
    "nobody can see it" look identical, and the mandatory human push looks
    like a bug.
    """
    import spq_paths

    events_dir = spq_paths.committed_events_dir(project_dir, cycle_id)
    if not os.path.isdir(events_dir):
        return []
    rel = os.path.relpath(events_dir, project_dir)
    code, tracked, _ = _git(project_dir, "ls-files", "--", rel)
    known = set(tracked.split()) if code == 0 else set()
    pending: List[str] = []
    import state_store

    for name in sorted(os.listdir(events_dir)):
        if not name.endswith(".json"):
            continue
        if os.path.join(rel, name) in known:
            continue
        event = state_store.read_json(os.path.join(events_dir, name))
        if event.get("unit_id"):
            pending.append(str(event["unit_id"]))
    return pending
